/// Reads one row back out of the two arrays above.
let private decodeRow i =
  let m = rowMain[i]
  let a = rowAttrs[i]
  { OpcodeByte = uint32 (m &&& 0xFFL)
    Opcode = enum<Opcode> (int ((m >>> 8) &&& 0xFFFFL))
    PrefixType = prefixTypes[a &&& 0x7]
    REXPrefixType = enum<REXPrefixType> ((a >>> 3) &&& 0xF)
    VectorLength = enum<VectorLength> ((a >>> 7) &&& 0x3)
    ModRM = modRMs[int ((m >>> 24) &&& 0xFFFL)]
    (* Copied so that no two rows share one array: nothing
       writes to these today, and this keeps it that way. *)
    Operands = Array.copy oprLists[int ((m >>> 36) &&& 0xFFFFL)]
    OpEn = enum<OpEn> ((a >>> 9) &&& 0x7F)
    Mode64 = enum<Mode64> ((a >>> 16) &&& 0x7)
    Compat = enum<CompatLegMode> ((a >>> 19) &&& 0x7)
    TupleType = enum<TupleType> ((a >>> 22) &&& 0x1F)
    SzCond = enum<SzCond> ((a >>> 27) &&& 0x7) }

/// The 256 slots of one opcode map.
let private buildMap (mapIdx: int) =
  Array.init 256 (fun slot ->
    let k = mapIdx * 256 + slot
    let first = slotStart[k]
    Array.init (slotStart[k + 1] - first) (fun j ->
      decodeRow (first + j)))

let (norOne: InstructionCore[][]) = buildMap 0
let (norTwo: InstructionCore[][]) = buildMap 1
let (norThree38: InstructionCore[][]) = buildMap 2
let (norThree3A: InstructionCore[][]) = buildMap 3
let (vexTwo: InstructionCore[][]) = buildMap 4
let (vexThree38: InstructionCore[][]) = buildMap 5
let (vexThree3A: InstructionCore[][]) = buildMap 6
let (evexTwo: InstructionCore[][]) = buildMap 7
let (evexThree38: InstructionCore[][]) = buildMap 8
let (evexThree3A: InstructionCore[][]) = buildMap 9
let (evexMap5: InstructionCore[][]) = buildMap 10
let (evexMap6: InstructionCore[][]) = buildMap 11
